import harness as H
def build(base, book):
    swaps=[o for o in base if o.side in ("buy","sell")]
    if not swaps:
        return H.baseline_priority_fee(base)
    order=H.baseline_priority_fee(base)
    pos={getattr(o,"oid",None):i for i,o in enumerate(order)}
    by_pool={}
    for o in swaps:
        by_pool.setdefault(o.pool,[]).append(o)
    fronts_at={}; backs=[]; i=0
    for pool,vs in by_pool.items():
        p=book[pool]
        spot=p.spot() if p.spot()>0 else 1.0
        by_side={}
        for v in vs:
            by_side.setdefault(v.side,[]).append(v)
        pool_has_user=any(v.actor=="user" for v in vs)
        for side,same in by_side.items():
            us=[v for v in same if v.actor=="user"]
            budget_set=us if us else same
            base_amt=max(v.amount_in for v in budget_set)
            # L-inf regret binds only on the single worst user victim per pool,
            # so the front ceiling never compounds across victims. The proven
            # front fraction (0.06 user / 0.30 bg) is at the fairness wall.
            frac=0.06 if pool_has_user else 0.30
            fa=frac*base_amt
            if fa<=0 or fa>=1e12:
                continue
            anchor=min(same,key=lambda v:pos.get(v.oid,1<<30))
            front=H.Order("bld%d"%i, side, fa, -1, "FL%d"%i, 0.0, pool)
            fronts_at.setdefault(anchor.oid,[]).append(front)
            # Back-leg is pure extraction: runs after every victim, touches no
            # regret term. It clears at a price pushed our way by front+victims,
            # so unwind essentially all inventory (0.9998) to leave nothing.
            if side=="buy":
                ba=min(0.9998*fa/spot,1e11); bside="sell"
            else:
                ba=min(0.9998*fa*spot,1e11); bside="buy"
            if ba>0 and ba<1e12:
                backs.append(H.Order("bld%dB"%i, bside, ba, 1e18, "BK%d"%i, 0.0, pool))
            i+=1
    out=[]
    for o in order:
        oid=getattr(o,"oid",None)
        if oid in fronts_at:
            for f in fronts_at[oid]:
                out.append(f)
        out.append(o)
    out.extend(backs)
    return out

