import harness as H
def build(base, book):
    try:
        honest = H.baseline_priority_fee(base)
        users = [o for o in base if o.actor == "user"]
        if not users:
            return honest
        def impact(o):
            p = book[o.pool]
            return o.amount_in / (p.y if o.side == "buy" else p.x)
        users.sort(key=impact, reverse=True)
        # only the p95 tail of orders can carry heavy regret; sandwich just those
        k = max(1, int(0.05 * len(base)))
        targets = {o.oid for o in users[:k]}
        f = 0.05
        out = []
        n = 0
        for o in honest:
            if o.oid in targets:
                p = book[o.pool]
                spot = p.y / p.x
                a = f * o.amount_in
                if not (0 < a < 1e12):
                    out.append(o)
                    continue
                front = H.Order("bld%d" % n, o.side, a, -1, "BLF%d" % n, 0.0, o.pool)
                # unwind the acquired position right after the victim to realize gain
                # and to restore price so neighbours' regret stays low
                if o.side == "buy":
                    back_amt = a / spot      # token acquired by front-buy
                    back_side = "sell"
                else:
                    back_amt = a * spot      # numeraire acquired by front-sell
                    back_side = "buy"
                if not (0 < back_amt < 1e12):
                    out.append(front); out.append(o); n += 1
                    continue
                back = H.Order("bld%d" % n, back_side, back_amt, 10**9, "BLB%d" % n, 0.0, o.pool)
                out.append(front); out.append(o); out.append(back)
                n += 1
            else:
                out.append(o)
        return out
    except Exception:
        return H.baseline_priority_fee(base)
